<template>
  <section class="presentation-panel">
    <header class="presentation-header">
      <nav :aria-label="t('presentationStudio')"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="changeTab(tab.id)">{{ t(tab.label) }}</button></nav>
    </header>

    <p v-if="draftError" class="interface-draft-error" role="alert">{{ draftError }}</p>
    <div v-if="activeTab === 'ui'" class="studio-grid">
      <section class="studio-card">
        <header><strong>{{ t('responsiveUi') }}</strong><span>{{ selectedUi?.name ?? t('noUiSelection') }}</span></header>
        <p>{{ t('responsiveUiHint') }}</p>
        <div class="button-row"><button class="primary" @click="createCanvas">+ {{ t('createCanvas') }}</button><button :disabled="!selectedUi" @click="saveUiScene">{{ t('saveUiScene') }}</button></div>
        <dl><div><dt>{{ t('layoutContainers') }}</dt><dd>{{ layoutCounts }}</dd></div><div><dt>{{ t('focusableControls') }}</dt><dd>{{ focusableCount }}</dd></div><div><dt>{{ t('reusableUiScenes') }}</dt><dd>{{ uiPrefabCount }}</dd></div></dl>
        <details open class="ui-hierarchy"><summary>{{ t('uiHierarchy') }}</summary><button v-for="entity in uiEntities" :key="entity.uuid" :class="{ active: selectedUi?.uuid === entity.uuid }" @click="selectUiEntity(entity.id)"><span>{{ entity.name }}</span><small>{{ entity.parentUuid ? t('childControl') : t('rootControl') }}</small></button></details>
      </section>
      <section class="studio-card responsive-preview-card">
        <header><strong>{{ t('responsivePreview') }}</strong><span>{{ previewPreset.label }}</span></header>
        <div class="responsive-tools"><select :aria-label="panelControlLabel('previewPreset')" v-model.number="previewPresetIndex"><option v-for="(preset,index) in previewPresets" :key="preset.label" :value="index">{{ preset.label }}</option></select><label><span>{{ interfaceCopy('dpi') }}</span><input v-model.number="previewDpi" type="number" min="0.5" max="4" step="0.25"></label><label><span>{{ t('safeArea') }}</span><input v-model="previewSafeArea" type="checkbox"></label><label><span>RTL</span><input v-model="previewRtl" type="checkbox"></label></div>
        <UiScenePreview :entities="physicsState.world.entities" :preset="previewPreset" :dpi="previewDpi" :safe-area="previewSafeArea" :rtl="previewRtl" :theme-reference="selectedThemeReference" :theme-draft="resolvedThemeDraft" />
        <div class="button-row"><button :disabled="!selectedCanvas" @click="applyPreviewToCanvas">{{ t('applyToCanvas') }}</button><span>{{ uiPerformance.controls }} {{ t('controls') }} · {{ uiPerformance.estimatedLayoutOperations }} {{ t('layoutOperations') }}</span></div>
        <div class="validation-list"><button v-for="issue in currentUiValidation.issues.slice(0,8)" :key="`${issue.code}:${issue.entityUuid}`" :class="issue.severity" @click="selectUiUuid(issue.entityUuid)"><strong>{{ issue.code }}</strong><span>{{ issue.entityName }} · {{ issue.message }}</span></button><p v-if="!currentUiValidation.issues.length">{{ t('responsiveValidationPassed') }}</p></div>
      </section>
      <section class="studio-card theme-editor">
        <header><strong>{{ t('uiThemes') }}</strong><button @click="newTheme">+ {{ t('newTheme') }}</button></header>
        <label><span>{{ t('uiTheme') }}</span><select :value="selectedThemeReference" @change="changeTheme"><option value="">{{ t('none') }}</option><option v-for="asset in themeAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
        <template v-if="themeDraft">
          <p class="draft-status">{{ themeDirty ? interfaceCopy('draft') : interfaceCopy('saved') }}</p>
          <p v-if="themeConflict" role="alert">{{ interfaceCopy('conflict') }} <button @click="discardDraft('theme')">{{ interfaceCopy('revert') }}</button></p>
          <label><span>{{ t('name') }}</span><input v-model="themeDraft.name" maxlength="120"></label>
          <label><span>{{ t('parentTheme') }}</span><select v-model="themeDraft.parentTheme"><option :value="null">{{ t('none') }}</option><option v-for="asset in themeAssets.filter(item => assetReference(item.uuid) !== selectedThemeReference)" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
          <label><span>{{ t('accentColor') }}</span><input v-model="themeAccent" type="color"></label>
          <label><span>{{ t('surfaceColor') }}</span><input v-model="themeSurface" type="color"></label>
          <label><span>{{ t('cornerRadius') }}</span><input v-model.number="themeRadius" type="number" min="0" max="100"></label>
          <p>{{ interfaceCopy('themeSpacing') }}</p>
          <label><span>{{ t('spacingToken') }}</span><input v-model.number="themeSpacing" type="number" min="0" max="100"></label>
          <label><span>{{ t('typographyToken') }}</span><input v-model.number="themeFontSize" type="number" min="6" max="160"></label>
          <label><span>{{ t('variants') }}</span><input :value="Object.keys(themeDraft.variants).join(', ')" readonly></label>
          <label><span>{{ t('compareTheme') }}</span><select v-model="themeCompareReference"><option value="">{{ t('none') }}</option><option v-for="asset in themeAssets.filter(item => assetReference(item.uuid) !== selectedThemeReference)" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
          <div class="theme-preview"><button disabled>{{ t('normal') }}</button><button class="hovered" disabled>{{ t('hovered') }}</button><input :aria-label="t('uiTheme') + ' · ' + t('preview')" readonly :placeholder="t('placeholder')"></div>
          <details><summary>{{ t('themeTokens') }}</summary><label v-for="group in themeTokenGroups" :key="group"><span>{{ group }}</span><input :value="Object.entries(themeDraft.tokens[group]).map(([key,value]) => `${key}=${value}`).join(', ')" readonly></label></details>
          <p class="theme-report">{{ themeUnused.length }} {{ t('unusedTokens') }} · {{ themeDifferences.length }} {{ t('themeDifferences') }}</p>
          <button class="primary" @click="saveTheme">{{ t('saveTheme') }}</button>
        </template>
      </section>
    </div>

    <div v-else-if="activeTab === 'localization'" class="localization-workspace">
      <aside class="locale-settings studio-card">
        <header><strong>{{ t('localization') }}</strong><span class="create-locale"><input :aria-label="t('locale')" v-model="newLocale" placeholder="en-US" maxlength="35"><button :disabled="!newLocale.trim()" @click="createLocale">+ {{ t('locale') }}</button></span></header>
        <label><span>{{ t('sourceLocale') }}</span><input v-model="localizationSettings.sourceLocale" @change="commitPresentation"></label>
        <label><span>{{ t('liveLocalePreview') }}</span><select v-model="localizationSettings.previewLocale" @change="commitPresentation"><option v-for="locale in knownLocales" :key="locale">{{ locale }}</option></select></label>
        <label><span>{{ t('pseudolocalization') }}</span><input v-model="localizationSettings.pseudolocalization" type="checkbox" @change="commitPresentation"></label>
        <label><span>{{ t('pseudolocalizationMode') }}</span><select v-model="localizationSettings.pseudolocalizationMode" @change="commitPresentation"><option value="accented">Accented</option><option value="expanded">Expanded</option><option value="bidi">BiDi</option></select></label>
        <label><span>{{ t('expansionRatio') }}</span><input v-model.number="localizationSettings.expansionRatio" type="number" min="0" max="2" step="0.05" @change="commitPresentation"></label>
        <label><span>{{ t('fallbackChain') }}</span><input :value="localizationSettings.fallbackChain.join(', ')" @change="setFallbacks"></label>
        <label><span>{{ t('numberStyle') }}</span><select v-model="localizationSettings.numberStyle" @change="commitPresentation"><option value="decimal">Decimal</option><option value="percent">Percent</option><option value="currency">Currency</option></select></label>
        <label v-if="localizationSettings.numberStyle === 'currency'"><span>{{ t('currency') }}</span><input v-model="localizationSettings.currency" maxlength="3" @change="commitPresentation"></label>
        <label><span>{{ t('dateStyle') }}</span><select v-model="localizationSettings.dateStyle" @change="commitPresentation"><option value="short">Short</option><option value="medium">Medium</option><option value="long">Long</option><option value="full">Full</option></select></label>
        <label><span>{{ t('timeZone') }}</span><input v-model="localizationSettings.timeZone" @change="commitPresentation"></label>
        <strong class="minor-heading">{{ t('buildLocales') }}</strong>
        <label v-for="locale in knownLocales" :key="locale" class="check"><input :checked="localizationSettings.buildLocales.includes(locale)" type="checkbox" @change="toggleBuildLocale(locale, $event)"><span>{{ locale }}</span></label>
      </aside>
      <section class="table-editor studio-card">
        <header><select :aria-label="t('chooseLocalizationTable')" :value="selectedLocaleReference" @change="changeLocale"><option value="">{{ t('chooseLocalizationTable') }}</option><option v-for="asset in localeAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.settings.localizationSettings.locale }} · {{ asset.name }}</option></select><button :disabled="!localeDraft" @click="addLocaleEntry">+ {{ t('entry') }}</button><button :aria-label="panelControlLabel('exportCsv')" :disabled="!localeDraft" @click="exportCsv">CSV ↓</button><button :aria-label="panelControlLabel('importCsv')" :disabled="!localeDraft" @click="csvImport?.click()">CSV ↑</button><button :aria-label="panelControlLabel('exportPo')" :disabled="!localeDraft" @click="exportPo">PO ↓</button><button :aria-label="panelControlLabel('importPo')" :disabled="!localeDraft" @click="poImport?.click()">PO ↑</button><button class="primary" :disabled="!localeDraft" @click="saveLocale">{{ t('saveTable') }}</button><input ref="csvImport" hidden type="file" accept=".csv,text/csv" @change="importCsv"><input ref="poImport" hidden type="file" accept=".po,text/x-gettext-translation" @change="importPo"></header>
        <div v-if="localeDraft" class="locale-meta"><label><span>{{ t('locale') }}</span><input v-model="localeDraft.locale"></label><label><span>{{ t('textDirection') }}</span><select v-model="localeDraft.direction"><option value="ltr">LTR</option><option value="rtl">RTL</option></select></label><label><span>{{ t('fallbackLocale') }}</span><input v-model="localeDraft.fallbackLocale"></label><label><span>{{ t('displayName') }}</span><input v-model="localeDraft.metadata.displayName"></label><label><span>{{ t('nativeName') }}</span><input v-model="localeDraft.metadata.nativeName"></label><label><span>{{ t('fontFallbacks') }}</span><input :value="localeDraft.fontFallbacks.join(', ')" @change="setFontFallbacks"></label></div>
        <div v-if="localeDraft" class="locale-rows"><article v-for="(value,key) in localeDraft.entries" :key="key"><code :title="localeDraft.contexts[key]">{{ key }}</code><input :aria-label="t('context') + ' · ' + key" v-model="localeDraft.contexts[key]" :placeholder="t('context')"><textarea :aria-label="panelControlLabel('translation', key)" :value="displayLocaleValue(value)" @change="setLocaleValue(key, $event)"></textarea><button :aria-label="t('removeEntry') + ' · ' + key" @click="removeLocaleEntry(key)">×</button></article></div>
        <footer v-if="localeDraft" class="localization-report"><strong>{{ t('localizationReport') }}</strong><span>{{ extractedKeys.length }} {{ t('keys') }} · {{ localizationAudit.length }} {{ t('issues') }}</span><code v-for="item in localizationAudit.slice(0,12)" :key="`${item.locale}:${item.key}:${item.code}`">{{ item.code }} · {{ item.locale }} · {{ item.key }} · {{ item.message }}</code></footer>
        <p v-else class="empty-state">{{ t('noLocalizationTable') }}</p>
      </section>
    </div>

    <div v-else-if="activeTab === 'audio'" class="audio-workspace" :style="{'--audio-properties-width':audioPropertiesWidth+'px'}">
      <section class="mixer studio-card">
        <header><strong>{{ t('audioMixer') }} · {{ audition ? audioCopy.audition : audioCopy.runtime }}</strong><button @click="addBus">+ {{ t('audioBus') }}</button></header>
        <p v-if="audioStatus" role="status">{{ audioStatus }}</p><p>{{ audioCopy.meterHint }}</p><div class="master-controls"><label><span>{{ t('masterVoiceLimit') }}</span><input v-model.number="audioSettings.mixer.masterVoiceLimit" type="number" min="1" max="1024" @change="commitAudio"></label><label><span>{{ t('outputDevice') }}</span><select v-model="audioSettings.mixer.outputDeviceId" @change="selectAudioOutput"><option v-for="device in audioDiagnostics.outputDevices" :key="device.id" :value="device.id">{{ device.label }}</option></select></label><label><span>{{ t('limiter') }}</span><input v-model="audioSettings.mixer.limiterEnabled" type="checkbox" @change="commitAudio"></label><label><span>{{ t('ceilingDb') }}</span><input v-model.number="audioSettings.mixer.limiterCeilingDb" type="number" min="-24" max="0" step=".1" @change="commitAudio"></label><button @click="captureSnapshot">+ {{ t('snapshot') }}</button><select :aria-label="t('snapshot')" v-model="audioSettings.mixer.activeSnapshot" @change="commitAudio"><option :value="null">{{ t('liveMix') }}</option><option v-for="snapshot in audioSettings.mixer.snapshots" :key="snapshot.id" :value="snapshot.id">{{ snapshot.name }}</option></select><label><span>{{ t('snapshotCrossfade') }}</span><input v-model.number="audioSettings.mixer.snapshotTransitionSeconds" type="number" min="0" max="30" step=".05" @change="commitAudio"></label></div>
        <div class="snapshot-list"><label v-for="snapshot in audioSettings.mixer.snapshots" :key="snapshot.id"><input :aria-label="t('snapshot') + ' · ' + t('name')" v-model="snapshot.name" @change="commitAudio"><input :aria-label="t('volume') + ' · ' + snapshot.name" v-model.number="snapshot.masterVolume" type="number" min="0" max="1" step=".01" @change="commitAudio"><button :aria-label="t('remove') + ' · ' + snapshot.name" :disabled="snapshot.id==='default'" @click="removeSnapshot(snapshot.id)">×</button></label></div>
        <div class="bus-list"><article v-for="bus in audioSettings.mixer.buses" :key="bus.id">
          <header><strong>{{ bus.name }}</strong><meter :aria-label="audioCopy.peak+' · '+bus.name" :class="meterClass(bus.id)" min="0" max="1" :value="audioDiagnostics.busMeterDetails[bus.id]?.peak ?? 0"></meter><output>{{ (audioDiagnostics.busMeterDetails[bus.id]?.peakDb ?? -120).toFixed(1) }} dB</output><button :aria-label="t('mute') + ' · ' + bus.name" :class="{ active: bus.mute }" @click="bus.mute = !bus.mute; commitAudio()">M</button><button :aria-label="panelControlLabel('solo', bus.name)" :class="{ active: bus.solo }" @click="bus.solo = !bus.solo; commitAudio()">S</button><button :aria-label="t('removeAudioBus') + ' · ' + bus.name" v-if="bus.id !== 'Master' && !defaultBuses.includes(bus.id)" @click="removeBus(bus.id)">×</button></header>
          <label><span>{{ t('name') }}</span><input v-model="bus.name" maxlength="80" @change="commitAudio"></label><label v-if="bus.id!=='Master'"><span>{{ audioCopy.routing }}</span><select v-model="bus.parent" @change="commitAudio"><option v-for="target in audioRouteOptions(bus)" :key="target.id" :value="target.id">{{ target.name }}</option></select></label><label><span>{{ t('volume') }}</span><input v-model.number="bus.gain" type="range" min="0" max="1" step="0.01" @change="commitAudio"><output>{{ Math.round(bus.gain * 100) }}%</output></label>
          <label><span>{{ t('voiceLimit') }}</span><input v-model.number="bus.voiceLimit" type="number" min="1" max="512" @change="commitAudio"></label>
          <details><summary>{{ t('effects') }} ({{ bus.effects.length }})</summary><div v-for="effect in bus.effects" :key="effect.id" class="effect-row"><select :aria-label="t('effect') + ' · ' + panelControlLabel('type')" v-model="effect.kind" @change="commitAudio"><option>LowPass</option><option>HighPass</option><option>Compressor</option><option>Delay</option><option>Reverb</option></select><input :aria-label="t('enabled') + ' · ' + effect.kind" v-model="effect.enabled" type="checkbox" @change="commitAudio"><input :aria-label="panelControlLabel('wet')" v-model.number="effect.wet" type="range" min="0" max="1" step="0.01" @change="commitAudio"><label v-if="effect.kind==='LowPass'||effect.kind==='HighPass'" class="effect-parameter"><span>{{ audioCopy.frequency }}</span><input v-model.number="effect.frequency" type="number" min="10" max="24000" @change="commitAudio"></label><label v-if="effect.kind==='LowPass'||effect.kind==='HighPass'" class="effect-parameter"><span>{{ audioCopy.q }}</span><input v-model.number="effect.q" type="number" min="0.0001" max="1000" step="0.1" @change="commitAudio"></label><label v-if="effect.kind==='Compressor'" class="effect-parameter"><span>{{ audioCopy.threshold }}</span><input v-model.number="effect.threshold" type="number" min="-100" max="0" @change="commitAudio"></label><label v-if="effect.kind==='Compressor'" class="effect-parameter"><span>{{ audioCopy.ratio }}</span><input v-model.number="effect.ratio" type="number" min="1" max="20" step="0.1" @change="commitAudio"></label><label v-if="effect.kind==='Delay'||effect.kind==='Reverb'" class="effect-parameter"><span>{{ audioCopy.time }}</span><input v-model.number="effect.time" type="number" min="0" :max="effect.kind==='Reverb'?3:5" step="0.01" @change="commitAudio"></label><label v-if="effect.kind==='Delay'" class="effect-parameter"><span>{{ audioCopy.feedback }}</span><input v-model.number="effect.feedback" type="number" min="0" max="0.95" step="0.01" @change="commitAudio"></label><button :aria-label="t('remove') + ' · ' + effect.kind" @click="bus.effects.splice(bus.effects.indexOf(effect),1); commitAudio()">×</button></div><button :disabled="bus.effects.length >= 8" @click="addEffect(bus)">+ {{ t('effect') }}</button></details>
          <details><summary>{{ t('sends') }} ({{ bus.sends.length }})</summary><div v-for="send in bus.sends" :key="`${send.target}-${bus.sends.indexOf(send)}`" class="effect-row"><select :aria-label="t('send') + ' · ' + t('target')" v-model="send.target" @change="commitAudio"><option v-for="target in audioRouteOptions(bus)" :key="target.id" :value="target.id">{{ target.name }}</option></select><input :aria-label="t('enabled') + ' · ' + send.target" v-model="send.enabled" type="checkbox" @change="commitAudio"><input :aria-label="t('volume') + ' · ' + send.target" v-model.number="send.gain" type="range" min="0" max="1" step="0.01" @change="commitAudio"><button :aria-label="t('remove') + ' · ' + send.target" @click="bus.sends.splice(bus.sends.indexOf(send),1); commitAudio()">×</button></div><button :disabled="bus.sends.length >= 16 || !audioRouteOptions(bus).length" @click="addSend(bus)">+ {{ t('send') }}</button></details>
          <details><summary>{{ t('automation') }} ({{ bus.automation.length }})</summary><div v-for="(point,index) in bus.automation" :key="index" class="automation-row"><input :aria-label="t('playhead') + ' · ' + index + 1" v-model.number="point.time" type="number" min="0" step=".05" @change="commitAudio"><input :aria-label="t('volume') + ' · ' + index + 1" v-model.number="point.gain" type="number" min="0" max="1" step=".01" @change="commitAudio"><button :aria-label="t('remove') + ' · ' + index + 1" @click="bus.automation.splice(index,1); commitAudio()">×</button></div><label><span>{{ t('loopSeconds') }}</span><input v-model.number="bus.automationLoopSeconds" type="number" min="0" max="3600" step=".1" @change="commitAudio"></label><button @click="addAutomationPoint(bus)">+ {{ t('automationPoint') }}</button></details>
        </article></div>
      </section>
      <aside class="audio-inspector studio-card"><PanelResizeHandle v-model="audioPropertiesWidth" orientation="vertical" :minimum="280" :maximum="600" :reset-value="380" reverse :label="audioCopy.resize" style="left:0;top:0;bottom:0" />
        <header><strong>{{ t('waveformPreview') }}</strong><select :aria-label="t('chooseAudioAsset')" v-model="selectedAudioGuid"><option value="">{{ t('chooseAudioAsset') }}</option><option v-for="asset in audioAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></header>
        <svg class="waveform" viewBox="0 0 512 100" preserveAspectRatio="none" role="slider" :aria-label="t('waveformEditor')" :aria-valuenow="waveformCursor" :aria-valuemin="0" :aria-valuemax="selectedAudio?.duration ?? 0" tabindex="0" @pointerdown="beginWaveformEdit" @keydown.left.prevent="nudgeWaveform(-1)" @keydown.right.prevent="nudgeWaveform(1)"><rect v-if="waveformSelection" class="loop-selection" :x="loopMarker(Math.min(waveformSelection.start,waveformSelection.end))" y="0" :width="Math.max(1,loopMarker(Math.max(waveformSelection.start,waveformSelection.end))-loopMarker(Math.min(waveformSelection.start,waveformSelection.end)))" height="100"/><polyline :points="waveformPoints" /><line v-if="selectedAudio" :x1="loopMarker(activeLoopStart)" y1="0" :x2="loopMarker(activeLoopStart)" y2="100" /><line v-if="selectedAudio && activeLoopEnd > 0" class="loop-end" :x1="loopMarker(activeLoopEnd)" y1="0" :x2="loopMarker(activeLoopEnd)" y2="100" /><line class="playhead-line" :x1="loopMarker(waveformCursor)" y1="0" :x2="loopMarker(waveformCursor)" y2="100" /></svg>
        <template v-if="selectedAudio"><label><span>{{ audioCopy.auditionBus }}</span><select v-model="auditionBus"><option v-for="bus in audioSettings.mixer.buses" :key="bus.id" :value="bus.id">{{ bus.name }}</option></select></label><p v-if="selectedAudio.settings.audioSettings.streaming">{{ audioCopy.streamHint }}</p><div class="waveform-tools"><button @click="previewWaveform">{{ waveformPlaying?'■':'▶' }} {{ t('preview') }}</button><output>{{ waveformCursor.toFixed(2) }}s</output><button @click="addLoopRegion">+ {{ t('loopRegion') }}</button></div><label><span>{{ t('normalizeAudio') }}</span><input v-model="selectedAudio.settings.audioSettings.normalize" type="checkbox" @change="commitAssetAudio"></label><label><span>{{ t('targetPeak') }}</span><input v-model.number="selectedAudio.settings.audioSettings.targetPeakDb" type="number" min="-24" max="0" step="0.1" @change="analyzeWaveform(true)"></label><label><span>{{ t('streamAudio') }}</span><input v-model="selectedAudio.settings.audioSettings.streaming" type="checkbox" @change="commitAssetAudio"></label><label><span>{{ t('activeLoopRegion') }}</span><select v-model="selectedAudio.settings.audioSettings.activeLoopRegion" @change="commitAssetAudio"><option :value="null">{{ t('legacyLoopMarkers') }}</option><option v-for="region in selectedAudio.settings.audioSettings.loopRegions" :key="region.id" :value="region.id">{{ region.name }}</option></select></label><label><span>{{ t('loopMarkers') }}</span><div><input :aria-label="t('loopRegion') + ' · ' + t('start')" v-model.number="activeLoopStart" type="number" min="0" :max="selectedAudio.duration" step="0.01" @change="commitAssetAudio"><input :aria-label="t('loopRegion') + ' · ' + panelControlLabel('end')" v-model.number="activeLoopEnd" type="number" min="0" :max="selectedAudio.duration" step="0.01" @change="commitAssetAudio"></div></label><article v-for="region in selectedAudio.settings.audioSettings.loopRegions" :key="region.id" class="loop-region-row"><input :aria-label="t('loopRegion') + ' · ' + t('name')" v-model="region.name" @change="commitAssetAudio"><input :aria-label="t('start') + ' · ' + region.name" v-model.number="region.start" @change="commitAssetAudio" type="number" min="0" :max="selectedAudio.duration" step=".01"><input :aria-label="panelControlLabel('end', region.name)" v-model.number="region.end" @change="commitAssetAudio" type="number" min="0" :max="selectedAudio.duration" step=".01"><button :aria-label="t('remove') + ' · ' + region.name" @click="removeLoopRegion(region.id)">×</button></article></template>
