async function removeLocaleEntry(key: string) { if (!localeDraft.value) return; const draft = localeDraft.value, before = JSON.stringify(draft), reference = selectedLocaleReference.value; const approved = await requestConfirmation({ title: t('removeEntry'), message: key, confirmLabel: t('removeEntry'), cancelLabel: t('cancel'), destructive: true }); if (approved && localeDraft.value === draft && selectedLocaleReference.value === reference && JSON.stringify(draft) === before) delete draft.entries[key]; else if (approved) draftError.value = interfaceCopy('stale') }
