function removeSnapshot(id: string) { audioSettings.mixer.snapshots = audioSettings.mixer.snapshots.filter(snapshot => snapshot.id !== id); if (audioSettings.mixer.activeSnapshot === id) audioSettings.mixer.activeSnapshot = null; commitAudio() }
function addDucking() { if (audioSettings.mixer.ducking.length >= 32 || audioSettings.mixer.buses.length < 2) return; audioSettings.mixer.ducking.push({ id: `duck-${Date.now().toString(36)}`, triggerBus: audioSettings.mixer.buses.find(bus => bus.id === 'SFX')?.id ?? audioSettings.mixer.buses[0].id, targetBus: audioSettings.mixer.buses.find(bus => bus.id === 'Music')?.id ?? audioSettings.mixer.buses[1].id, reductionDb: -12, attack: .04, release: .35, enabled: true }); commitAudio() }
function commitAudio() { Object.assign(audioSettings, normalizeAudioSettings(audioSettings)); pushHistory('Edit audio mixer', 'project:audio') }
function commitAssetAudio() { const asset = selectedAudio.value; if (!asset) return; const settings = asset.settings.audioSettings; settings.loopStart = Math.min(asset.duration, Math.max(0, Number(settings.loopStart) || 0)); settings.loopEnd = Math.min(asset.duration, Math.max(0, Number(settings.loopEnd) || 0)); if (settings.loopEnd > 0 && settings.loopEnd < settings.loopStart) settings.loopEnd = settings.loopStart; settings.loopRegions = settings.loopRegions.slice(0,64).map(region=>({...region,start:Math.min(asset.duration,Math.max(0,Number(region.start)||0)),end:Math.min(asset.duration,Math.max(0,Number(region.end)||0))})).filter(region=>region.end>region.start); if(settings.activeLoopRegion&&!settings.loopRegions.some(region=>region.id===settings.activeLoopRegion))settings.activeLoopRegion=null; assetState.generation++; pushHistory('Edit audio import settings', `asset:${asset.uuid}`) }
