function beginWaveformEdit(event:PointerEvent){if(event.button!==0||!selectedAudio.value)return;disposeWaveformDrag?.();const svg=event.currentTarget as SVGSVGElement,asset=selectedAudio.value,start=waveformTime(event,svg),previous={time:waveformCursor.value,selection:waveformSelection.value?{...waveformSelection.value}:null,playing:waveformPlaying.value};svg.setPointerCapture(event.pointerId);waveformCursor.value=start;waveformSelection.value={start,end:start};audition?.seek(start,false)
